import { BlogCoverMorph } from '@/components/ds/ui/blog-cover-morph';
import { RingBackdrop } from '@/components/ds/ui/ring-backdrop';
type Post = { slug: string; title: string };

/**
 * Dot-art covers for the homepage blog cards, rendered by scripts/generate-blog-cover-dots.mjs with
 * the Context Dot Shader pipeline (filled and hollow dots on a uniform grid). Each file is a
 * single-colour mask, so the same art serves the white card in blue and the blue card in white.
 * The motif is picked from the post's slug/title.
 */

export type BlogCoverMotif = 'blocked' | 'trends' | 'pages' | 'integration' | 'images' | 'extract';

export type BlogCardSurface = 'paper' | 'blue';

// Paper and Blue palettes from the Context Dot Shader.
export const BLOG_CARD_PALETTES: Record<BlogCardSurface, { background: string; dots: string }> = {
	paper: { background: 'var(--ds-color-bg-default)', dots: 'var(--ds-color-brand)' },
	blue: { background: 'var(--ds-color-brand)', dots: 'var(--ds-color-white)' },
};

/** Alternates white and blue, so the three-column grid reads as a checkerboard. */
export function blogCardSurface(index: number): BlogCardSurface {
	return index % 2 === 0 ? 'paper' : 'blue';
}

const MOTIF_KEYWORDS: [BlogCoverMotif, RegExp][] = [
	['blocked', /error|40[0-9]|429|50[0-9]|520|block|anti-detect|captcha|proxy|proxies|detect|rate-limit/],
	['integration', /mcp|cursor|claude|set-up|setup|integrat|pipeline|sdk|webhook/],
	['images', /image|logo|screenshot|photo|favicon|visual/],
	['extract', /extract|pydantic|schema|structured|json|product-data|parse/],
	['pages', /javascript|render|browser|crawl|sitemap|page|markdown/],
	['trends', /trend|agentic|future|state-of|announc|introducing|best-/],
];

const FALLBACK_ORDER: BlogCoverMotif[] = ['pages', 'trends', 'integration', 'blocked', 'extract', 'images'];

export function getBlogCoverMotif(post: Pick<Post, 'slug' | 'title'>): BlogCoverMotif {
	const haystack = `${post.slug} ${post.title}`.toLowerCase();
	for (const [motif, pattern] of MOTIF_KEYWORDS) {
		if (pattern.test(haystack)) return motif;
	}
	let hash = 0;
	for (const char of post.slug) hash = (hash * 31 + char.charCodeAt(0)) >>> 0;
	return FALLBACK_ORDER[hash % FALLBACK_ORDER.length];
}

/** Assign motifs to a list so neighbouring cards never repeat the same artwork. */
export function assignBlogCoverMotifs(posts: Pick<Post, 'slug' | 'title'>[]): BlogCoverMotif[] {
	const used = new Set<BlogCoverMotif>();
	return posts.map((post) => {
		let motif = getBlogCoverMotif(post);
		if (used.has(motif) && used.size < FALLBACK_ORDER.length) {
			motif = FALLBACK_ORDER.find((candidate) => !used.has(candidate)) ?? motif;
		}
		used.add(motif);
		if (used.size === FALLBACK_ORDER.length) used.clear();
		return motif;
	});
}

const BACKDROP_PITCH = 14;
export const BACKDROP_RING_OPACITY: Record<BlogCardSurface, number> = { paper: 0.14, blue: 0.22 };

// A faint ring tile behind the art. `space` repeats only whole tiles, so no ring is ever cut at the card's edge.
// Used as a mask: the ring's color comes from the element's background-color, so tokens apply.
export function backdropStyle(surface: BlogCardSurface) {
	const tile = backdropTile(surface);
	return { backgroundColor: BLOG_CARD_PALETTES[surface].dots, maskImage: tile, WebkitMaskImage: tile, maskRepeat: 'space', WebkitMaskRepeat: 'space' } as const;
}

export function backdropTile(surface: BlogCardSurface) {
	const colour = 'black';
	const ring = `<svg xmlns='http://www.w3.org/2000/svg' width='${BACKDROP_PITCH}' height='${BACKDROP_PITCH}'><circle cx='${BACKDROP_PITCH / 2}' cy='${BACKDROP_PITCH / 2}' r='3.5' fill='none' stroke='${colour}' stroke-opacity='${BACKDROP_RING_OPACITY[surface]}' stroke-width='1'/></svg>`;
	return `url("data:image/svg+xml,${ring.replace(/</g, '%3C').replace(/>/g, '%3E')}")`;
}

// Three layers: the ring backdrop, then the card colour painted through the art's halo (each dot grown into a blob)
// to clear the backdrop around the art, then the art itself. Halo and art share one mask box, so they line up.
export function BlogCoverArt({ motif, surface }: { motif: BlogCoverMotif; surface: BlogCardSurface }) {
	const palette = BLOG_CARD_PALETTES[surface];
	const artMask = `url(/blog-covers/${motif}.svg) center / contain no-repeat`;
	const haloMask = `url(/blog-covers/${motif}-halo.svg) center / contain no-repeat`;
	return (
		<div aria-hidden="true" className="relative h-full w-full">
			{/* Drawn ring by ring so none is sliced by the card's rounded corners. */}
			<RingBackdrop color={palette.dots} opacity={BACKDROP_RING_OPACITY[surface]} className="inset-0" />
			<BlogCoverMorph motif={motif} dotColor={palette.dots} backgroundColor={palette.background}>
				<div className="absolute inset-0" style={{ backgroundColor: palette.background, mask: haloMask, WebkitMask: haloMask }} />
				<div className="absolute inset-0" style={{ backgroundColor: palette.dots, mask: artMask, WebkitMask: artMask }} />
			</BlogCoverMorph>
		</div>
	);
}

import type { CoverScene } from '@/components/ds/ui/blog-cover-scenes';
import { DOT_ABSENT, DOT_FILLED, DOT_HOLLOW, type DotGrid } from '@/components/ds/ui/dot-morph-dots';
import { clearGooField, createGooField, fuseGooField, readGooField } from '@/components/ds/ui/dot-morph-goo';
import type { DotMorphFrame } from '@/components/ds/ui/dot-morph-player';

/**
 * The Context Dot Shader from scripts/generate-blog-cover-dots.mjs, run live: a scene is drawn small, each grid cell's
 * coverage and tone are read back, and every cell becomes a filled dot, a hollow dot or nothing. The constants below
 * mirror the script's, so a scene held still lands on the same dots as the generated cover.
 */

export const COVER_GRID: DotGrid = { columns: 80, rows: 60, pitch: 10, dotRadius: 3.4, ringStroke: 1.6, haloRadius: 16 };
const CELL_COUNT = COVER_GRID.columns * COVER_GRID.rows;

const TONE_AMOUNT = 0.75;
const CONTRAST = 2.2;
const DITHER = 0.22;
const TEXTURE = 0.12;
const FILLED_AT = 0.55;
const HOLLOW_AT = 0.16;
const MIN_COVERAGE = 0.08;

// The canvas anti-aliases every pixel into its true area coverage, so two samples a side already measure a cell exactly.
const SAMPLES_PER_CELL = 2;
const FIELD_WIDTH = COVER_GRID.columns * SAMPLES_PER_CELL;
const FIELD_HEIGHT = COVER_GRID.rows * SAMPLES_PER_CELL;
const FIELD_SCALE = SAMPLES_PER_CELL / COVER_GRID.pitch;

const BAYER = [0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5].map((value) => (value + 0.5) / 16);

const clamp01 = (value: number) => Math.min(1, Math.max(0, value));

function hashNoise(x: number, y: number) {
	const n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453;
	return n - Math.floor(n);
}

function smoothNoise(x: number, y: number) {
	const x0 = Math.floor(x);
	const y0 = Math.floor(y);
	const fx = x - x0;
	const fy = y - y0;
	const sx = fx * fx * (3 - 2 * fx);
	const sy = fy * fy * (3 - 2 * fy);
	const top = hashNoise(x0, y0) + (hashNoise(x0 + 1, y0) - hashNoise(x0, y0)) * sx;
	const bottom = hashNoise(x0, y0 + 1) + (hashNoise(x0 + 1, y0 + 1) - hashNoise(x0, y0 + 1)) * sx;
	return top + (bottom - top) * sy;
}

const CELL_TEXTURE = new Float32Array(CELL_COUNT);
const CELL_DITHER = new Float32Array(CELL_COUNT);
for (let row = 0; row < COVER_GRID.rows; row++) {
	for (let column = 0; column < COVER_GRID.columns; column++) {
		CELL_TEXTURE[row * COVER_GRID.columns + column] = (smoothNoise(column / 3.2, row / 3.2) - 0.5) * TEXTURE;
		CELL_DITHER[row * COVER_GRID.columns + column] = (BAYER[(row & 3) * 4 + (column & 3)] - 0.5) * DITHER * 0.5;
	}
}

function classify(cell: number, coverage: number, tone: number) {
	if (coverage < MIN_COVERAGE) return DOT_ABSENT;
	const contrasted = clamp01((tone - 0.5) * CONTRAST + 0.5);
	const value = Math.sqrt(coverage) * (1 - TONE_AMOUNT * (1 - clamp01(contrasted + CELL_TEXTURE[cell]))) + CELL_DITHER[cell];
	if (value >= FILLED_AT) return DOT_FILLED;
	return value >= HOLLOW_AT ? DOT_HOLLOW : DOT_ABSENT;
}

/** Reads a generated cover back into one dot state per grid cell. */
export function parseCoverDots(svg: string): Uint8Array {
	const states = new Uint8Array(CELL_COUNT);
	const hollowGroupStart = svg.indexOf('<g fill="none"');
	const hollowFrom = hollowGroupStart === -1 ? Number.POSITIVE_INFINITY : hollowGroupStart;
	for (const circle of svg.matchAll(/<circle cx="([\d.]+)" cy="([\d.]+)"/g)) {
		const column = Math.floor(Number(circle[1]) / COVER_GRID.pitch);
		const row = Math.floor(Number(circle[2]) / COVER_GRID.pitch);
		if (column >= COVER_GRID.columns || row >= COVER_GRID.rows) continue;
		states[row * COVER_GRID.columns + column] = circle.index < hollowFrom ? DOT_FILLED : DOT_HOLLOW;
	}
	return states;
}

export function createCoverShader(scene: CoverScene) {
	const goo = createGooField(FIELD_WIDTH, FIELD_HEIGHT);
	const crisp = createGooField(FIELD_WIDTH, FIELD_HEIGHT);
	const scratch = new Float32Array(FIELD_WIDTH * FIELD_HEIGHT);
	const states = new Uint8Array(CELL_COUNT);
	// A scene is drawn from the morph and spin alone, so a frame that repeats both (a held or unspun cover) is unchanged.
	let lastMorph = Number.NaN;
	let lastSpin = Number.NaN;

	return (frame: DotMorphFrame) => {
		if (frame.morph === lastMorph && frame.spin === lastSpin) return states;
		lastMorph = frame.morph;
		lastSpin = frame.spin;
		clearGooField(goo, FIELD_SCALE);
		clearGooField(crisp, FIELD_SCALE);
		scene.draw({ goo: goo.context, crisp: crisp.context }, frame);
		readGooField(goo);
		readGooField(crisp);

		const sigma = scene.gooSigma(frame.morph) * FIELD_SCALE;
		if (sigma > 0.002) fuseGooField(goo, scratch, sigma);

		for (let row = 0; row < COVER_GRID.rows; row++) {
			for (let column = 0; column < COVER_GRID.columns; column++) {
				let coverage = 0;
				let darkness = 0;
				for (let sampleY = 0; sampleY < SAMPLES_PER_CELL; sampleY++) {
					const rowStart = (row * SAMPLES_PER_CELL + sampleY) * FIELD_WIDTH + column * SAMPLES_PER_CELL;
					for (let sampleX = 0; sampleX < SAMPLES_PER_CELL; sampleX++) {
						const pixel = rowStart + sampleX;
						const showsThrough = 1 - crisp.coverage[pixel];
						coverage += crisp.coverage[pixel] + goo.coverage[pixel] * showsThrough;
						darkness += crisp.darkness[pixel] + goo.darkness[pixel] * showsThrough;
					}
				}
				const cell = row * COVER_GRID.columns + column;
				states[cell] = coverage > 0 ? classify(cell, coverage / (SAMPLES_PER_CELL * SAMPLES_PER_CELL), darkness / coverage) : DOT_ABSENT;
			}
		}
		return states;
	};
}

import type { BlogCoverMotif } from '@/components/ds/ui/blog-cover-art';
import { COVER_GRID, createCoverShader, parseCoverDots } from '@/components/ds/ui/blog-cover-dot-shader';
import { loadCoverScene } from '@/components/ds/ui/blog-cover-scenes';
import type { DotPalette } from '@/components/ds/ui/dot-morph-dots';
import { createDotMorphPlayer, type DotMorphPlayer } from '@/components/ds/ui/dot-morph-player';

interface BlogCoverMorphOptions {
	canvas: HTMLCanvasElement;
	motif: BlogCoverMotif;
	palette: DotPalette;
	onPlayingChange: (isPlaying: boolean) => void;
}

export async function createBlogCoverMorph({ canvas, motif, palette, onPlayingChange }: BlogCoverMorphOptions): Promise<DotMorphPlayer> {
	const [cover, scene] = await Promise.all([
		fetch(`/blog-covers/${motif}.svg`).then((response) => {
			if (!response.ok) throw new Error(`Could not load the ${motif} cover`);
			return response.text();
		}),
		loadCoverScene(motif),
	]);

	return createDotMorphPlayer({
		canvas,
		palette,
		onPlayingChange,
		source: {
			grid: COVER_GRID,
			fit: 'contain',
			restingDots: parseCoverDots(cover),
			spinSpeed: scene.spinSpeed,
			spinPeriod: scene.spinPeriod,
			sample: createCoverShader(scene),
		},
	});
}

'use client';

import type { BlogCoverMotif } from '@/components/ds/ui/blog-cover-art';
import { useHoverDotMorph, type LoadDotMorph } from '@/components/ds/ui/use-hover-dot-morph';
import { cx as cn } from '@/components/ds/ui/cx';
import { useCallback, useRef, type ReactNode } from 'react';

interface BlogCoverMorphProps {
	motif: BlogCoverMotif;
	dotColor: string;
	backgroundColor: string;
	/** The generated cover, shown whenever the morph is at rest. */
	children: ReactNode;
}

/** Morphs the cover as its card scrolls into view and while it is hovered or keyboard-focused, then hands back to the static art. */
export function BlogCoverMorph({ motif, dotColor, backgroundColor, children }: BlogCoverMorphProps) {
	const canvasRef = useRef<HTMLCanvasElement>(null);
	const load = useCallback<LoadDotMorph>(
		async (canvas, onPlayingChange) => {
			const { createBlogCoverMorph } = await import('@/components/ds/ui/blog-cover-morph-engine');
			return createBlogCoverMorph({ canvas, motif, palette: { dots: dotColor, background: backgroundColor }, onPlayingChange });
		},
		[motif, dotColor, backgroundColor]
	);
	const isPlaying = useHoverDotMorph(canvasRef, load, { playOnView: true });

	return (
		<div className="absolute inset-0">
			<div className={cn('absolute inset-0', isPlaying && 'invisible')}>{children}</div>
			<canvas ref={canvasRef} className={cn('absolute inset-0 h-full w-full', !isPlaying && 'invisible')} />
		</div>
	);
}

// ds-override: grayscale luminance art drawn offscreen and sampled into dot states; these values are never painted
import type { BlogCoverMotif } from '@/components/ds/ui/blog-cover-art';
import type { DotMorphFrame } from '@/components/ds/ui/dot-morph-player';

/**
 * The hover choreography for each blog cover. At `morph` 0 a scene draws the same shaded illustration that
 * scripts/generate-blog-cover-dots.mjs rasterizes (keep the two in step), and by `morph` 1 it has become its
 * second picture. `spin` drives whatever keeps moving while the card stays hovered.
 *
 * Shapes on the goo layer are blurred and re-cut by the dot shader, so they melt into each other as they meet;
 * the crisp layer is for line work that must survive that.
 */

type Context = CanvasRenderingContext2D;

export interface CoverLayers {
	goo: Context;
	crisp: Context;
}

export interface CoverScene {
	spinSpeed: number;
	spinPeriod: number;
	/** Blur, in cover units, that fuses the goo layer's shapes. */
	gooSigma: (morph: number) => number;
	draw: (layers: CoverLayers, frame: DotMorphFrame) => void;
}

const TAU = Math.PI * 2;
const CENTER_X = 400;
const CENTER_Y = 300;

const clamp01 = (value: number) => Math.min(1, Math.max(0, value));
const lerp = (from: number, to: number, amount: number) => from + (to - from) * amount;
const phase = (morph: number, start: number, end: number) => clamp01((morph - start) / (end - start));
const easeInOut = (t: number) => (t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2);
const easeOutBack = (t: number) => 1 + 2.70158 * (t - 1) ** 3 + 1.70158 * (t - 1) ** 2;
const swell = (morph: number, start: number, end: number) => Math.sin(Math.PI * phase(morph, start, end));
const grey = (from: number, to: number, amount: number) => {
	const level = Math.round(lerp(from, to, amount));
	return `rgb(${level},${level},${level})`;
};

function linearFill(context: Context, x0: number, y0: number, x1: number, y1: number, from: string, to: string) {
	const gradient = context.createLinearGradient(x0, y0, x1, y1);
	gradient.addColorStop(0, from);
	gradient.addColorStop(1, to);
	return gradient;
}

function sphereFill(context: Context, x: number, y: number, radius: number, light = '#d9d9d9', dark = '#050505') {
	const gradient = context.createRadialGradient(x - radius * 0.3, y - radius * 0.4, 0, x - radius * 0.3, y - radius * 0.4, radius * 1.6);
	gradient.addColorStop(0, light);
	gradient.addColorStop(0.55, '#6b6b6b');
	gradient.addColorStop(1, dark);
	return gradient;
}

function fillCircle(context: Context, x: number, y: number, radius: number, fill: string | CanvasGradient) {
	context.fillStyle = fill;
	context.beginPath();
	context.arc(x, y, radius, 0, TAU);
	context.fill();
}

const REQUEST_COUNT = 8;
const REQUEST_RADIUS = 42;
const REQUEST_ORBIT = { x: 250, y: 215 };
// The opened shackle reaches up into the ring, so the ring widens and the padlock steps back to let the requests pass.
const OPEN_ORBIT = { x: 278, y: 242 };
const OPEN_REQUEST_RADIUS = 36;
const OPEN_PADLOCK_SCALE = 0.86;
const PADLOCK_CENTER_Y = 365;
const BLOCKED_REQUESTS = new Set([1, 4, 7]);
// Requests bunch up where the ring passes this angle, close enough to fuse, then string out again.
const JAM_ANGLE = Math.PI * 0.2;
const JAM_DEPTH = 0.55;

const blocked: CoverScene = {
	spinSpeed: 0.5,
	spinPeriod: TAU / REQUEST_COUNT,
	gooSigma: (morph) => 15 * easeInOut(phase(morph, 0.15, 0.7)),
	draw({ goo, crisp }, { morph, spin }) {
		const jam = easeInOut(phase(morph, 0.15, 0.7));
		const release = easeInOut(phase(morph, 0, 0.5));
		const blockedMark = 1 - phase(morph, 0, 0.25);
		for (let request = 0; request < REQUEST_COUNT; request++) {
			const lap = (request / REQUEST_COUNT) * TAU - Math.PI / 2 + spin;
			const crowding = (1 - Math.cos(lap - JAM_ANGLE + Math.PI)) / 2;
			const angle = lap + JAM_DEPTH * jam * Math.sin(lap - JAM_ANGLE + Math.PI);
			const x = CENTER_X + Math.cos(angle) * lerp(REQUEST_ORBIT.x, OPEN_ORBIT.x, release);
			const y = CENTER_Y + Math.sin(angle) * lerp(REQUEST_ORBIT.y, OPEN_ORBIT.y, release);
			const radius = lerp(REQUEST_RADIUS, OPEN_REQUEST_RADIUS, release) * (1 + 0.3 * jam * crowding);
			// Let through, a request darkens from a pale, mostly hollow ball into a solid one.
			fillCircle(goo, x, y, radius, sphereFill(goo, x, y, radius, grey(0xf0, 0x8c, release), grey(0x4a, 0, release)));
			if (!BLOCKED_REQUESTS.has(request) || blockedMark === 0) continue;
			goo.globalAlpha = blockedMark;
			goo.strokeStyle = '#000';
			goo.lineWidth = 12;
			goo.beginPath();
			goo.moveTo(x - 24, y - 24);
			goo.lineTo(x + 24, y + 24);
			goo.moveTo(x + 24, y - 24);
			goo.lineTo(x - 24, y + 24);
			goo.stroke();
			goo.globalAlpha = 1;
		}

		const lift = 30 * easeOutBack(phase(morph, 0.2, 0.55));
		const swing = 0.42 * easeOutBack(phase(morph, 0.4, 0.85));
		const stepBack = lerp(1, OPEN_PADLOCK_SCALE, release);
		crisp.save();
		crisp.translate(CENTER_X, PADLOCK_CENTER_Y);
		crisp.scale(stepBack, stepBack);
		crisp.translate(-CENTER_X, -PADLOCK_CENTER_Y);

		crisp.save();
		crisp.translate(470, 290 - lift);
		crisp.rotate(swing);
		crisp.translate(-470, -290);
		crisp.strokeStyle = linearFill(crisp, 0, 160, 0, 290, '#1a1a1a', '#8a8a8a');
		crisp.lineWidth = 30;
		crisp.beginPath();
		crisp.moveTo(330, 290);
		crisp.lineTo(330, 230);
		crisp.arc(CENTER_X, 230, 70, Math.PI, 0);
		// The hinge leg grows by the lift, so it stays seated in the body while the free leg comes out.
		crisp.lineTo(470, 290 + lift);
		crisp.stroke();
		crisp.restore();

		crisp.fillStyle = linearFill(crisp, 0, 280, 0, 450, '#1a1a1a', '#8a8a8a');
		crisp.beginPath();
		crisp.roundRect(290, 280, 220, 170, 18);
		crisp.fill();

		crisp.save();
		crisp.translate(CENTER_X, 345);
		crisp.rotate((Math.PI / 2) * easeInOut(phase(morph, 0, 0.3)));
		fillCircle(crisp, 0, 0, 24, '#fff');
		crisp.fillRect(-10, 5, 20, 56);
		crisp.restore();
		crisp.restore();
	},
};

const ORBITS = [
	{ x: 330, y: 210 },
	{ x: 200, y: 128 },
];
const ORBIT_DASH = [16, 14];
const ORBIT_DASH_TRAVEL = (30 * 6) / TAU;

interface Planet {
	x: number;
	y: number;
	radius: number;
	orbit: number;
	laps: number;
}

const PLANETS: Planet[] = [
	{ x: 582, y: 246, radius: 34, orbit: 1, laps: 2 },
	{ x: 112, y: 352, radius: 48, orbit: 0, laps: 1 },
	{ x: 640, y: 468, radius: 26, orbit: 0, laps: 1 },
];

const BRAIN_LOBES = [
	{ x: 30, y: -56, radius: 32 },
	{ x: 76, y: -44, radius: 32 },
	{ x: 100, y: -2, radius: 30 },
	{ x: 84, y: 42, radius: 30 },
	{ x: 38, y: 58, radius: 30 },
];
const BRAIN_FISSURE = 6;
const BRAIN_FOLD_WIDTH = 12;
const THINKING_PLANET_RADIUS = 26;

function drawBrainHalf(context: Context, side: 1 | -1) {
	context.save();
	context.scale(side, 1);
	context.beginPath();
	context.rect(BRAIN_FISSURE, -110, 160, 220);
	context.clip();
	context.fillStyle = '#000';
	context.beginPath();
	context.ellipse(48, 0, 60, 62, 0, 0, TAU);
	for (const lobe of BRAIN_LOBES) {
		context.moveTo(lobe.x + lobe.radius, lobe.y);
		context.arc(lobe.x, lobe.y, lobe.radius, 0, TAU);
	}
	context.fill();

	context.globalCompositeOperation = 'destination-out';
	context.lineWidth = BRAIN_FOLD_WIDTH;
	context.lineCap = 'round';
	context.beginPath();
	context.moveTo(BRAIN_FISSURE, -14);
	context.bezierCurveTo(34, -18, 54, -34, 52, -60);
	context.moveTo(124, 20);
	context.bezierCurveTo(92, 14, 68, 26, 62, 54);
	context.stroke();
	context.restore();
}

const trends: CoverScene = {
	spinSpeed: 0.45,
	spinPeriod: TAU,
	gooSigma: (morph) => 15 * swell(morph, 0.05, 0.9),
	draw({ goo, crisp }, { morph, spin }) {
		crisp.strokeStyle = '#9a9a9a';
		crisp.lineWidth = 7;
		crisp.setLineDash(ORBIT_DASH);
		ORBITS.forEach((orbit, index) => {
			crisp.lineDashOffset = -spin * ORBIT_DASH_TRAVEL * (index + 1);
			crisp.beginPath();
			crisp.ellipse(CENTER_X, CENTER_Y, orbit.x, orbit.y, 0, 0, TAU);
			crisp.stroke();
		});
		crisp.setLineDash([]);

		const think = easeInOut(phase(morph, 0.1, 0.75));
		goo.globalAlpha = 1 - think;
		fillCircle(goo, CENTER_X, CENTER_Y, 82, sphereFill(goo, CENTER_X, CENTER_Y, 82, '#8c8c8c', '#000'));
		goo.globalAlpha = think;
		goo.save();
		goo.translate(CENTER_X, CENTER_Y);
		const grow = lerp(0.7, 1, easeOutBack(phase(morph, 0.2, 0.9)));
		goo.scale(grow, grow);
		drawBrainHalf(goo, 1);
		drawBrainHalf(goo, -1);
		goo.restore();
		goo.globalAlpha = 1;

		// The generated cover sets two planets a little off their orbit line; they settle onto it as they start to travel.
		const settle = easeInOut(phase(morph, 0, 0.5));
		for (const planet of PLANETS) {
			const orbit = ORBITS[planet.orbit];
			const restX = (planet.x - CENTER_X) / orbit.x;
			const restY = (planet.y - CENTER_Y) / orbit.y;
			const reach = lerp(Math.hypot(restX, restY), 1, settle);
			const angle = Math.atan2(restY, restX) + spin * planet.laps;
			const x = CENTER_X + Math.cos(angle) * orbit.x * reach;
			const y = CENTER_Y + Math.sin(angle) * orbit.y * reach;
			const radius = planet.orbit === 1 ? lerp(planet.radius, THINKING_PLANET_RADIUS, settle) : planet.radius;
			fillCircle(goo, x, y, radius, sphereFill(goo, x, y, radius));
		}
	},
};

interface TextLine {
	y: number;
	width: number;
	height: number;
}

function drawPage(context: Context, width: number, height: number, border: number, inset: number, lines: TextLine[]) {
	const left = -width / 2;
	const top = -height / 2;
	context.fillStyle = linearFill(context, left, top, -left, -top, '#ffffff', '#d0d0d0');
	context.fillRect(left, top, width, height);
	context.fillStyle = '#000';
	for (const line of lines) context.fillRect(left + inset, top + line.y, line.width, line.height);
	context.strokeStyle = '#000';
	context.lineWidth = border;
	context.strokeRect(left, top, width, height);
}

